const crypto = global.get("crypto");
const secret = env.get("LINE_CHANNEL_SECRET");
const signature = msg.req.headers["x-line-signature"];

// エラー時は後続処理を行わずHTTP応答だけ返す
function reject(statusCode, message) {
    msg.statusCode = statusCode;
    msg.payload = message;
    return [null, msg];
}

// 設定と受信データの確認
if (!secret || !crypto) {
    node.error("署名検証の設定が不足しています");
    return reject(500, "Server configuration error");
}

if (!Buffer.isBuffer(msg.payload)) {
    return reject(400, "Invalid request body");
}

// 署名がない場合は拒否
if (typeof signature !== "string" ||
    !/^[A-Za-z0-9+/]{43}=$/.test(signature)) {
    return reject(401, "Unauthorized");
}

// 受信した本文を変更せずに署名を計算
const calculated = crypto
    .createHmac("sha256", secret)
    .update(msg.payload)
    .digest();

const received = Buffer.from(signature, "base64");

// タイミング攻撃に配慮して比較
if (received.length !== calculated.length ||
    !crypto.timingSafeEqual(received, calculated)) {
    return reject(401, "Unauthorized");
}

// 署名検証が成功してからJSONを解析
try {
    msg.lineWebhook = JSON.parse(msg.payload.toString("utf8"));
} catch (err) {
    return reject(400, "Invalid JSON");
}

msg.statusCode = 200;
msg.payload = "OK";
return [msg, null];

const allowedUserId = env.get("LINE_ALLOWED_USER_ID");
const events = msg.lineWebhook?.events;

// 許可ユーザーが未設定なら処理しない
if (!allowedUserId) {
    node.error("LINE_ALLOWED_USER_IDが未設定です");
    return null;
}

if (!Array.isArray(events)) {
    return null;
}

for (const event of events) {
    // 許可したユーザーからの1対1のメッセージのみ受け付ける
    if (
        event.source?.type !== "user" ||
        event.source?.userId !== allowedUserId
    ) {
        continue;
    }

    // 「写真」の場合だけ撮影指示を生成
    if (
        event.type === "message" &&
        event.message?.type === "text" &&
        event.message.text === "写真"
    ) {
        const requestToken =
            event.webhookEventId || event.message.id;

        if (!requestToken) continue;

        node.send({
            payload: {
                command: "capture",
                requestToken
            }
        });
    }
}

return null;

const id = msg.payload?.requestToken;

if (typeof id !== "string" || !id) {
    return null;
}

const now = Date.now();
const ttl = 24 * 60 * 60 * 1000; // 24時間

// 過去に処理したイベントIDを取得
const seen = context.get("seenEventIds") || {};

// 古い履歴を削除
for (const key of Object.keys(seen)) {
    if (now - seen[key] >= ttl) {
        delete seen[key];
    }
}

// 処理済みなら撮影指示を破棄
if (Object.prototype.hasOwnProperty.call(seen, id)) {
    return null;
}

// 初回のイベントIDを記録
seen[id] = now;
context.set("seenEventIds", seen);

return msg;
